  /** The grade's rate in force on the sheet's today, or null when none is. */
  protected pctOf(grade: string): string | null {
    return this.pctByGrade().get(grade) ?? null;
  }

  /**
   * The sum of the dues of their claims that count, each already rounded to cents; null (n/a) when
   * their grade has no rate in force today and none of those claims has a due fixed when settled or bound by a statement,
   * nor a due under another grade they had on its date or under a rate not in force today.
   */
  /**
   * The parts shares move, in cents: per claim that counts, what its holders' parts add up to, and per holder
   * each part they hold with its claim. A part is the claim's amount times the share divided by 100, times
   * the rate of the holder's own grade on its date divided by 100, rounded like the claim; a holder whose
   * grade has no rate then holds none. A settled claim's parts are frozen: its settled due times the share
   * divided by 100, rounded half to even.
   */
  private readonly shareParts = computed(() => {
    const late = this.session.late();
    const given = new Map<number, number>();
    const held = new Map<number, { claim: Claim; cents: number }[]>();
    for (const c of this.claims()) {
      if (c.shares.length === 0 || !this.counts(c)) continue;
      const up = halfUp(roundsOn(c, this.claimsOf(c.personId)), late);
      for (const s of c.shares) {
        let part: number;
        if (c.settledDue !== null) {
          part = shareCents(cents(c.settledDue), cents(s.share));
        } else {
          const pct = this.pctOnOf(s.personId)(c.date, c.added);
          if (pct === null) continue;
          part = holderCents(cents(c.amount), cents(s.share), cents(pct), up);
        }
        given.set(c.id, (given.get(c.id) ?? 0) + part);
        held.set(s.personId, [...(held.get(s.personId) ?? []), { claim: c, cents: part }]);
      }
    }
    return { given, held };
  });

  /** The parts of others' claims the person holds. */
  private heldPartsOf(personId: number): { claim: Claim; cents: number }[] {
    return this.shareParts().held.get(personId) ?? [];
  }

  private uncappedDueCents(p: Person): number | null {
    const theirs = this.claimsOf(p.id);
    const counted = theirs.filter(this.counts);
    const pctOn = this.pctOnOf(p.id);
    const graceOn = this.graceOnOf(p.id);
    const floor = this.session.floorCentsOn;
    const late = this.session.late();
    const gradeToday = this.gradeOf(p);
    const today = this.session.today();
    const otherRate = (c: Claim) => {
      const rates = this.ratesOf(gradeOn(p, c.date));
      return today !== null && rateInLevels(rates, c.date, c.added) !== rateInLevels(rates, today);
    };
    const fixed = (c: Claim) => c.settledDue !== null || (isBound(c) && c.statedDue !== null)
      || ((gradeOn(p, c.date) !== gradeToday || otherRate(c)) && claimDueCents(c, pctOn, floor, late, roundsOn(c, theirs), graceOn) !== null);
    const held = this.heldPartsOf(p.id);
    if (this.pctOf(gradeToday) === null && !counted.some(fixed) && held.length === 0) return null;
    const given = this.shareParts().given;
    return counted.reduce((sum, c) => sum + (claimDueCents(c, pctOn, floor, late, roundsOn(c, theirs), graceOn) ?? 0) - (given.get(c.id) ?? 0), 0)
      + held.reduce((sum, h) => sum + h.cents, 0);
  }

  /** The sheet's cap in cents, or null when there is none. */
  private readonly capCents = computed(() => {
    const cap = this.session.cap();
    return cap === null ? null : cents(cap);
  });

  /** Their due-total in cents, at most the cap less their cut total (not below 0.00); null (n/a) is not capped. */
  private dueTotalCents(p: Person): number | null {
    const total = this.uncappedDueCents(p);
    const cap = this.capCents();
    return total === null || cap === null ? total : Math.min(total, Math.max(0, cap - this.cutTotalOf(p.id)));
  }
